# 逐段翻译，索引0到最后
ts[0]['modern'] = "【论主译者与缘起偈开端】【义解】开府仪同三司、特进、试鸿胪卿、肃国公、食邑三千户、赐紫、赠司空、谥大鉴、正号大广智大兴善寺三藏沙门不空奉诏译。缘起流转偈颂：从一支生三支，从三支转生六支，六支分成二支再成六支，从六支又生六支；从六支出三支，这三支又各分三支，三支再生四支，四支再生三支。"
ts[1]['modern'] = "【缘起流转偈与十二支总说】【义解】从三支生一支，那一支再生七支，其中所有的苦，释迦牟尼佛说都总摄在这里。十二种差别，有智慧的人说都是空，因为缘生支的作用力，应当知晓这十二支法：无明（无知）、业、识、名色、六根（六处）、三和（触）、领纳（受）、渴爱（爱）、取、集（有）、生、熟（老）、最后终结（死），按次第排列。初、八、九三支是烦恼，第二、第十两支是业，其余七支都是苦，这三类总摄十二支法。"
ts[2]['modern'] = "【三世两重因果与缘起还灭】【义解】最初两支是过去世，最后两支是未来世，其余八支是现在世，这就是三世的缘起法。烦恼生业，业感召果报，果报又再生烦恼，烦恼又生业，也由业而有果报。离开烦恼哪里有业？离开业哪里有果报？没有果报就离开烦恼，这三者各各本自寂灭。五支作为因生果，就是烦恼和业；七支作为果报，就是七种苦，应当知晓。"
ts[3]['modern'] = "【缘起性空与缘起诸分】【义解】因中没有果，果中也没有因，因中也没有因，果中也没有果，有智慧的人和空性相应。世间的四种缘起支分，因为因果和合而有，烦恼、业、果报和合，应当承认有六分。因为由节段摄持的缘故，有二节、三略，因果杂合为节，三节、四总略。二三二三二的次第，苦位里有五法：作者、胎藏、界、境界、转生、流行。"
ts[4]['modern'] = "【八种果与缘起无我中道】【义解】迷惑果、发起果、等流果分为二种，在相应根分当中，一一对应三、二种分；热恼果、缺短果、转出果、等流果，在其余相应分中，对应二、一、一、一法。这十二种法和合就是缘生，没有众生、没有寿命，空性要以智慧了知。没有我、没有我所，在无我无我的状态里，四种无明是空，其余支分也都是这样，远离断、常二边见，这就是中道。"
ts[5]['modern'] = "【圣教佐证缘生即空】【义解】如果觉悟成就了，觉的本体就是诸佛；觉悟之后在大众中，圣仙（佛陀）宣说无我法。曾经在《城喻经》里，导师宣说这个义理；《迦旃延经》里说正见和空见，《破逻遇拏经》（张宿名）里也宣说殊胜的空义。如果正确了知缘生，他的知见就和空相应；如果不知缘生，也就不能了知那个空性。"
ts[6]['modern'] = "【恶取空与正见空的区别】【义解】如果对空生起慢心，对五蕴不生厌离，那就叫恶趣空，会迷失缘生的义理。因为不迷失缘生，远离慢心，他就能了知空性；又因为厌离五蕴，所以对业果不迷惑。业作为缘相续生死，也不是不依凭这个业；空性作为缘就有这些业报的受用具足。十二支的差别，前面已经说了缘生，那些烦恼、业、苦三类如法总摄，从三支生二支，从二支生七支，从七支又生三支。"
ts[7]['modern'] = "【缘起流转譬喻，本论释论分科】【义解】轮回就这样转动，一切法都是因果，从空生空，从法生法。依凭缘生烦恼，依凭缘也生业，依凭缘也生果报，没有一法不是依缘而生。用诵习、灯、印、镜、音声、日光、种子、醋这八个譬喻，五蕴相续没有转移的时候，有智慧的人应当观察这因果二法。《缘生三十论》本颂完毕，《缘生三十论》，我现在随顺次第解释。"
ts[8]['modern'] = "【释初句：从一生于三】【义解】「从一生于三，从三转生六，六二二更六，从六亦生六。」从一生于三：「一」指的是无知，这个无知名叫无明。对于苦、集、灭、道四谛不能觉知，所以叫无知；由无明的缘故，就有福行、非福行、不动行，名叫三行，包括身行、口行、心行等，都从无明转生。"
ts[9]['modern'] = "【释十二支流转前半：识、名色、六处、六触】【义解】从三转生六：从三行转生六识身，就是眼识、耳识、鼻识、舌识、身识、意识。「六二」：那六识身转生二种，就是名、色。「二更六」：名色二种转生六处，就是眼处、耳处、鼻处、舌处、身处、意处。从六亦生六：从那六处转生六触，就是眼触、耳触、鼻触、舌触、身触、意触。"
ts[10]['modern'] = "【释十二支流转后半：三受、三爱、四取、三有】【义解】「从六有于三，此三复有三，三复生于四，四复生于三。」从六有于三：从那六触转生三受，就是乐受、苦受、不苦不乐受。此三复有三：从那三受转生三种爱，就是欲爱、有爱、无有爱。从三复生于四：从那三种爱转生四取，就是欲取、见取、戒禁取、我语取。从四复生于三：从那四取转生三有，就是欲有、色有、无色有。"
ts[11]['modern'] = "【释生老死七苦支，总摄一切苦】【义解】「从三生于一，彼一复生七，于中所有苦，牟尼说皆摄。」从三生于一：还以那三有作为缘，生未来世一种生。彼一复生七：从这一生又转生老、死、愁、叹、苦、忧、恼七种。于中所有苦牟尼说皆摄：在这里面，从无明开始、到老死苦结束，无量种苦，世尊简略说都被这十二支总摄。"
ts[12]['modern'] = "【十二支皆空，缘生支义】【义解】「十二种差别，智士说为空，缘生支力故，应知十二法。」十二种差别智士说为空：无明等十二种差别有十二支，这一切都是自性空，应当知道这里所说的只是空，法从空生、空从法生，法是由缘生支的缘故而有。应知十二法：如果按次第由生支的作用力，这十二法就应当这样了知。其中迷惑的相状是无明，行支处积集当来果相的是行，识支处次第受生支转起的相是识，名色支处名身色身和合相是名色，六处支处安置诸根相是六处，触支处眼、色、识三事共聚相是触，受支处对可爱非可爱颠倒受用相是受，爱支处无厌足相是爱，取支处执持摄取相是取，有支处名身色身相是有，生支处五蕴生起相是生，老支处成熟相是老，死支处命根断相是死，愁支处匆遽忧惶相是愁，叹支处啼哭发声相是叹，苦支处身体逼恼相是苦，忧支处心逼恼相是忧，诸热恼支处损害相是恼。"
ts[13]['modern'] = "【十二支异名释义】【义解】「无知与业识，名色根三和，领渴及以取，集出熟后边。」在这里面，无知就是无明，业就是行，识就是了别，名色是五蕴聚，根就是六处，三和就是触，领纳就是受，渴就是爱，取就是执持，受用（集）就是有，起（出）就是生，熟就是老，后边就是死。"
ts[14]['modern'] = "【三摄十二法：烦恼业苦】【义解】又这些差别相的总摄，我按次第说明。这里面有烦恼、业的差别：初、八、九是烦恼，第二、第十是业，其余七都是苦，三类总摄十二法。三种烦恼是：无明、爱、取；二种业是：行、有；七种果报是：识、名色、六处、触、受、生、老死，这十二法被这三类总摄。"
ts[15]['modern'] = "【三世十二支】【义解】还有时间差别：最初两支是过去世，最后两支是未来世，其余八支是现在世，这就是三世的缘起法。无明、行最初二支是过去世，生、老死最后二支是未来世，识、名色、六处、触、受、爱、取、有八支是现在世。又这些都是各各次第相生的：烦恼感召业，业感召果报，果报还生烦恼，烦恼复生业，也由业而有果报。"
ts[16]['modern'] = "【缘起还灭义】【义解】烦恼、业、报三种如前面所说：由烦恼的缘故有业，由业的缘故有果报，还由果报的缘故有烦恼，由烦恼的缘故有业，由业的缘故有果报。有人问：由烦恼尽的缘故各各寂灭，义理是怎样的？回答说：离开烦恼哪里有业？离开业哪里有果报？没有果报就离开烦恼，这三者各各本自寂灭。"
ts[17]['modern'] = "【因果分：五因七果】【义解】如果这个心没有烦恼染污就不会集业，如果不造业就不受果报，如果果报灭了也就不生烦恼，这样这三者各各寂灭。又这些有因果的分别：五支作为因生果，称为烦恼业；七支作为果，是七种苦，应当知晓。五种因名为烦恼业，就是前面所说的无明、行、爱、取、有。"
ts[18]['modern'] = "【因果性空四句】【义解】七种果转生，也就是前面所说的七种苦：识、名色、六处、触、受、生、老死。又这因果两种都是空：因中没有果，果中也没有因，因中也没有因，果中也没有果，有智慧的人和空相应（梵本是一首偈，这里作一句）。如果这里所说的因果二种，因空果也空，果空因也空；因空因本身也空，果空果本身也空，在这四句的边际上应当与空相应。"
ts[19]['modern'] = "【四支分与六分义】【义解】还有其他分别：世间四种支分，因为因果和合而有，烦恼、业、果报和合，应当许为六支。世间四种支因果合故有：所说的三世五种因，连同七种果，总略为四种分，次第四种分：无明、行，过去世二法是初分；识、名色、六处、触、受，现在世是第二分；爱、取、有，也是现在世是第三分；生、老死，未来世二法是第四分，这就是四种分。烦恼业果结合许为六分：烦恼、业、报三种，结合为二根，就成六分。"
ts[20]['modern'] = "【二根六分义】【义解】在这里面，无明乃至受以无明为根，爱乃至老死以爱为根。无明根中，无明是烦恼分，行是业分，识、名色、六处、触、受是报分；爱根中，爱、取是烦恼分，有是业分，生、老死是报分。"
ts[21]['modern'] = "【节分总略：三节四略】【义解】又有节分总略：因为有节所摄持的缘故，有二节和三略，因果杂合为节，三节、四总略。以有节作为根本，发起二节：有、生之间是第一节，行、识之间是第二节，这二节都是业果节；受、爱之间因果共杂是第三节。这三节又总略为四种：无明、行二种是第一总略，识、名色、六处、触、受五种是第二总略，爱、取、有三种是第三总略，生、老死二种是第四总略，这就是三节和四总略。"
ts[22]['modern'] = "【苦位五法义】【义解】又这些法中位和时的差别：二三二三二的次第，苦位有五法：作者、胎藏、界、境转、生、流行。法中，无明、行说为二种；识、名色、六处说为三种；触、受说为二种；爱、取、有说为三种；又二者，生、老死说为二种。这五法，是苦位中的作者、胎藏、境界、发转、出生、于中流行，按数量应当知晓：无明、行二种是苦位中的作者，识、名色、六处三种是苦位中的胎藏，触、受二种是苦位中的境界，爱、取、有三种是苦位中的发转，生、老死二种是苦位中的流行。"
ts[23]['modern'] = "【无明根四果：迷惑、发起、报、等流】【义解】又果的差别：迷惑果、发起果、报果、等流果分为二种，在相应根分当中，一一对应三、二种分。如前面所说，这无明根和爱根，在无明根初分中迷惑、发起、报、等流，名为四种果，按数量次第一一对应三、二的分位，应当相应：无明是迷惑果，行是发起果，识、名色、六处是报果，触、受是等流果。"
ts[24]['modern'] = "【爱根四果：热恼、缺短、转出、等流】【义解】还有其余残果：热恼果、缺短果、转出果、等流果，在其余相应分中，对应二、一、一、一法。如前面所说的第二爱根分中，热恼、缺短、转生、等流果等，按其数分二一一一，在这些法中应当相应：爱、取是热恼果，有是缺短果，生是转出果，老死是等流果。这样这些就有八种果。"
ts[25]['modern'] = "【缘生无我空义】【义解】这十二种支分，和合的缘故就是缘生，没有众生、没有寿命，空性要以智慧了知。这样以无明为初（古译无明，今译无知才是正确的），老死为后，有十二支，因为和合殊胜的缘故各各缘生，而没有众生、没有寿命、空无，应当以智慧了知。其中没有众生，因为不牢固的缘故；没有寿命，因为无我的缘故；空，就是没有作者，因为没有作者的缘故。"
ts[26]['modern'] = "【一切支无我空义】【义解】没有我、没有我所，在无我无我的状态里，四种无明是空，其余支分也都是这样。无明是无我，这之中无明是无我所；因为无我的缘故，无我之中没有无明，四种无知、无我所之中也没有无知空。就像四种次第无明是空，这样行等其余支分也都是空，应当了知。"
ts[27]['modern'] = "【离二边是中道，觉者即诸佛】【义解】远离断、常二边见，这就是中道；如果觉悟成就了，觉的本体就是诸佛。执有是常见，执无是断见，这二边由缘起生，在诸法有中，如果远离二边就契合中道。如果不知道这个义理，诸外道就堕入二边；如果觉悟了这个道理，就是一切诸佛，只有佛在世间能成就这个义理，不是其他人能做到的。"
ts[28]['modern'] = "【《城喻经》说无我义】【义解】觉悟之后在大众中，圣仙宣说无我法。曾经在《城喻经》里，导师已经说过这个义理：觉悟了这个中道之后，在诸大众中，佛宣说无我、无我所。「你们这些比丘应当知道：执着我、我所，是愚痴凡夫、少闻的人，在假施设的法中执着有我和我所。比丘，生的时候只是苦生，灭的时候只是苦灭。」"
ts[29]['modern'] = "【诸经说空义，缘生正知即空】【义解】如《城喻经》里导师已经说过义理。另外，《迦旃延经》里说正见和空见，《破逻具拏经》（张宿名）里也说殊胜的空义，这三部经以及其他地方，这样的义理世尊已经广泛宣说。如果正确了知缘生，他的知见就和空相应；如果不知缘生，也就不知那个空。"
ts[30]['modern'] = "【恶取空迷缘生义】【义解】对于前面所说的缘生如果有正知，他的知见没有别的，知道什么呢？就是知道空。缘生若不知亦不知空：对于这个缘生如果不了知，对于那个空也不能悟入，应当知晓。如果对空生起慢心，就对五蕴不生厌离；如果起无见，就会迷失缘生的义理。"
ts[31]['modern'] = "【空慢过患与四见】【义解】对空生起慢心就不生厌离，如果起空慢就对五蕴不生厌离；如果有断无见就迷失缘生义理，如果因为无见迷失这缘生义理，就在四种见中随便取哪一种：一是断见，二是常见，三是自在天化作说，四是一切宿业作说。"
ts[32]['modern'] = "【正知缘生、离慢知空、不迷业果】【义解】因为不迷失缘生，远离慢心，就能了知空；又因为厌离五蕴，所以不迷惑业果。缘生不迷故离慢彼知空：对于前面所说的各各缘生如果没有迷心，在执取我、我所中如果能离慢，就能如法悟入空性。及厌于蕴故不迷于业果：因为在五蕴中执取我、我所的缘故，就遍于世间轮转不息。"
ts[33]['modern'] = "【业续生死，缘生空义】【义解】在五蕴中生起厌离心的缘故，对于业果相续就没有颠倒也不迷惑。又这个义理如何？业作为缘相续生死，也不是不依凭这个业；以空为缘就有这些业报的受用具足。业作缘续生亦非不缘此：烦恼、业、报如前面所说，以善、不善业，推遣众生在上下诸趣相续而生，如果不是这个业就不能作缘；"
ts[34]['modern'] = "【业报空义，总摄十二支】【义解】如果不是这样，就会有不作业而受报、已经作业而失坏的过失。空缘当有此业报受用具：如果由这些善、不善业有果报受用，自性是空、本来没有我，作缘发生，彼性是空也应当了知。那个义理现在再简略说明：十二支差别，前面已经说过缘生，那些烦恼、业、苦三类，按如法的方式总摄在其中。"
ts[35]['modern'] = "【有轮流转义】【义解】以无明为初，老死为后，是十二支缘生差别，如前面所说；其中三支是烦恼，二支是业，七支是苦，都已经总摄入。从三生二，从二生七，从七复生三，有轮这样转动：无明、爱、取三种烦恼所生行、有二种业，那二种业所生识、名色、六处、触、受、生、老死七支。"
ts[36]['modern'] = "【有轮相续，空法生空法】【义解】那七支中如前面所说还生三种烦恼，那三种烦恼又生二种业，二种业再生七支果，所以二种次第不断，这个有轮就这样转动。因果生诸世，没有别的众生，只是空法，还自生空法：无明、行、爱、取、有五种名为因，识、名色、六处、触、受、生、老死七种名为果。"
ts[37]['modern'] = "【缘起无作者，唯空假名】【义解】这些法普遍世间，所谓我、众生、寿命、生者、丈夫、人、作者，这些分别全是虚诳，应当了知。它们怎么生起呢？只是空法还自生空法，就是自性空中假名安立烦恼、业、果，只有空的假名烦恼业果法生起，这就是它的义理。"
ts[38]['modern'] = "【诸法皆从缘生，八喻总说】【义解】依凭缘生烦恼，依凭缘也生业，依凭缘也生果报，没有一法不是有因缘的。如果有烦恼就有种种无量业，以及种种业所生果报，这些都依因和众缘，应当知道没有一法是无因缘的。又为了说明那个义理，现在说譬喻：诵习、灯、印、镜、音声、日光、种子、醋，众生五蕴相续没有转移，有智慧的人应当观察这因果二法。"
ts[39]['modern'] = "【八喻释义：不常不断、不移而转】【义解】如同诵习：有教诵的人、受诵的人，教诵的内容没有转移到受诵者那里，为什么呢？因为教诵者仍在原处，所以教诵的内容不相续，为什么？因为自法不能从自体生的缘故。如同灯次第生起，不是初灯的火焰转移到后面，也不是第二火焰无因而生；这样印和像二种、面和镜中影像二种、音声和回响二种、日和火二种、种子和芽二种、醋和舌上唾液二种。"
ts[40]['modern'] = "【内外十义：非常非断等】【义解】这所有的二法，都没有转移，也不是不生，也不是无因而生。那因果二种五蕴相续次第转，不是前蕴转移到后蕴，而后蕴也不是不生，也不是无因而生。有智慧的人对于这个五蕴相续次第、没有转移，应当正确观察。另外内外相应有十种义，都应当了知。其中外十种是：一、非常，二、非断，三、不移转，四、因果相系没有中间，五、非彼自体，六、非别异，七、无作者，八、非无因，九、刹那灭，十、同类果相系。"
ts[41]['modern'] = "【外十义释义：种子喻】【义解】外在法中：种子灭尽无余，所以是非常；芽出生，所以是非断；种子灭尽无余之后，芽本来无而今有生起，所以是不移转；因果相续没有断绝、因果相继，所以无中间；种子和芽有差别，所以非彼自体；从种子出生芽，所以非别异；因缘和合所以无作者；以种子为因，所以非无因；种子、芽、茎、枝、叶、花、果展转相生，所以是刹那灭；甜、醋、咸、苦、辛、涩随因的差别果转起，所以是同类果相系。"
ts[42]['modern'] = "【内十义释义：五蕴相续】【义解】同类果相系，其中内十种是：一、死有边五蕴灭尽无余所以非常；二、得次生位五蕴所以非断；三、死有边五蕴灭尽无余之后，次生位五蕴本来无而今有生起，所以不移转；四、五蕴相续没有断绝，因果相继所以无中间；五、死有边和次生位五蕴有差别，所以非彼自体；"
ts[43]['modern'] = "【内十义释义续】【义解】六、从死有五蕴出生次生五蕴，所以非别异；七、因缘和合所以无作者；八、以烦恼业为因，所以非无因；九、迦逻罗（凝滑）、頞浮陀（疱）、箄尸（软肉）、伽那（坚肉）、奄佉（形位）、出胎、婴孩、童子、少年、长老等，展转相生，所以是刹那灭；十、善不善熏习随因差别果转起，所以是同类果相系。"
ts[44]['modern'] = "【三偈结义，四谛总摄】【义解】又有三首偈：如同灯焰转生，识身也是这样，前际和后际，也没有积集。不生也有生，破坏不和合，所生也没有住，而这样作业转动。如果对于彼缘生，能观照了知是空，如果了知彼假名施设，就契合中道。在这里面，无明、行、爱、取、有是集谛，识、名色、六处、触、受、生、老死是苦谛。"
ts[45]['modern'] = "【道谛释义，论终】【义解】这十二支中，道谛就是让它们灭、证灭的方便，就是四念处、四正勤、四如意足、五根、五力、七觉支、八圣道，名为道谛。"

